		},
	} {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()
			cacheDir := t.TempDir()
			backing := filepath.Join(cacheDir, "bigstore")
			if err := os.Mkdir(backing, 0o700); err != nil {
