		t.Fatal(err)
	}
	items, err := os.ReadDir(filepath.Join(cacheDir, "records", "v1"))
	if err != nil {
		t.Fatal(err)
	}
	if len(items) != 1 || items[0].Name() != strings.Repeat("f", 64)+".json.gz" {
		names := make([]string, 0, len(items))
		for _, item := range items {
