	file, _, ok := openContainedRegularFile(pinned, repo, relPath)
	if !ok {
		return "", false
	}
	defer file.Close()
	buf := make([]byte, limit)
	n, err := io.ReadFull(file, buf)
	if err != nil && err != io.EOF && err != io.ErrUnexpectedEOF {
