		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(outside, "app.go"), []byte("package outside\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	pinned := pinnedRootIdentity(nil, repo)

	stop := make(chan struct{})
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
