func TestFallbackRefusesAReplacedRepositoryRoot(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("repointing a directory symlink mid-scan is not the Windows shape of this race")
	}
	parent := t.TempDir()
