		t.Fatal(err)
	}

	got, ok := readFallback(pinned, repo, "app.go", 0, nil)
	if ok {
		t.Fatalf("fallback read %q from the REPLACEMENT tree after the root was pinned elsewhere", got)
	}
	if _, ok := readPrefixFallback(pinned, repo, "app.go", 8); ok {
